package com.zxl.zxlaiagent.knowledge;

import java.sql.*;
import java.util.*;
import static com.zxl.zxlaiagent.knowledge.KnowledgeDatabase.statement;

/** A short DB reservation, embedding outside transactions, then a fenced atomic publication. */
public final class KnowledgeService {
    public record Manifest(String documentId,String sourceName,String status,String activeRevision,long version,int chunkCount,String errorCode){}
    public record Detail(Manifest document,String rawText,List<KnowledgeText.Chunk> chunks){}
    public record ImportResult(String outcome,Manifest document){}
    public record Hit(String chunkId,String documentId,String revisionId,String text,int startUtf16,int endUtf16,int startLine,int endLine,double distance){}
    public record Search(String query,String embeddingMode,List<Hit> hits){}
    public static final class Conflict extends RuntimeException {public Conflict(){super("A newer import or deletion superseded this build; retry explicitly");}}
    private final KnowledgeDatabase db;private final String tenant;private final KnowledgeEmbedding embedding;
    public KnowledgeService(KnowledgeDatabase db,String tenant,KnowledgeEmbedding embedding){if(embedding.identity().length()>120||embedding.dimensions()<1||embedding.dimensions()>4096)throw new IllegalArgumentException("Invalid model profile");this.db=db;this.tenant=tenant;this.embedding=embedding;}
    private Manifest manifest(ResultSet r)throws SQLException{return new Manifest(r.getString("document_id"),r.getString("source_name"),r.getString("status"),r.getString("active_revision"),r.getLong("version"),r.getInt("chunk_count"),r.getString("error_code"));}
    private Manifest find(Connection c,String id,boolean lock)throws SQLException{try(var s=statement(c,"SELECT * FROM knowledge_document WHERE tenant_id=? AND document_id=?"+(lock?" FOR UPDATE":""),tenant,id);var r=s.executeQuery()){if(!r.next())throw new NoSuchElementException("Document not found");return manifest(r);}}
    public List<Manifest> list(){return db.tx(c->{List<Manifest> list=new ArrayList<>();try(var s=statement(c,"SELECT * FROM knowledge_document WHERE tenant_id=? ORDER BY updated_at DESC,document_id",tenant);var r=s.executeQuery()){while(r.next())list.add(manifest(r));}return list;});}
    public Detail detail(String id){return db.tx(c->{var m=find(c,id,true);String raw="";List<KnowledgeText.Chunk> chunks=new ArrayList<>();if(m.activeRevision()!=null){try(var s=statement(c,"SELECT raw_text FROM knowledge_revision WHERE tenant_id=? AND document_id=? AND revision_id=?",tenant,id,m.activeRevision());var r=s.executeQuery()){if(r.next())raw=r.getString(1);}try(var s=statement(c,"SELECT * FROM knowledge_chunk WHERE tenant_id=? AND document_id=? AND revision_id=? ORDER BY ordinal",tenant,id,m.activeRevision());var r=s.executeQuery()){while(r.next())chunks.add(new KnowledgeText.Chunk(r.getString("chunk_id"),r.getInt("ordinal"),r.getString("text_content"),r.getInt("start_utf16"),r.getInt("end_utf16"),r.getInt("start_line"),r.getInt("end_line"),r.getString("title_path")));}}return new Detail(m,raw,chunks);});}
    public ImportResult importDocument(String id,String source,String raw){
        var p=KnowledgeText.prepare(tenant,id,source,raw,400,embedding.identity(),embedding.dimensions());
        long version=db.tx(c->{try(var s=statement(c,"INSERT INTO knowledge_document(tenant_id,document_id,source_name,status) VALUES(?,?,?,'EMPTY') ON CONFLICT DO NOTHING",tenant,id,source)){s.executeUpdate();}var m=find(c,id,true);if(p.revisionId().equals(m.activeRevision())&&!"DELETED".equals(m.status()))return -1L;
            try(var s=statement(c,"UPDATE knowledge_document SET version=version+1,source_name=?,status=CASE WHEN active_revision IS NULL THEN 'BUILDING' ELSE status END,error_code=NULL,updated_at=now() WHERE tenant_id=? AND document_id=?",source,tenant,id)){s.executeUpdate();}
            try(var s=statement(c,"INSERT INTO knowledge_revision(tenant_id,document_id,revision_id,raw_hash,normalized_hash,profile_hash,raw_text,model_identity,state,expected_chunks) VALUES(?,?,?,?,?,?,?,?,'BUILDING',?) ON CONFLICT(tenant_id,document_id,revision_id) DO UPDATE SET state='BUILDING'",tenant,id,p.revisionId(),p.rawHash(),p.normalizedHash(),p.profileHash(),raw,embedding.identity(),p.chunks().size())){s.executeUpdate();}return m.version()+1;});
        if(version<0)return new ImportResult("UNCHANGED",detail(id).document());
        List<String> vectors=new ArrayList<>();try{for(var chunk:p.chunks())vectors.add(KnowledgeEmbedding.vectorLiteral(embedding.embed(chunk.text()),embedding.dimensions()));}catch(RuntimeException e){recordFailure(id,p.revisionId(),version,"EMBEDDING_FAILED");throw e;}
        try {return db.tx(c->{var m=find(c,id,true);if(m.version()!=version)throw new Conflict();
            try(var s=statement(c,"DELETE FROM knowledge_chunk WHERE tenant_id=? AND document_id=? AND revision_id=?",tenant,id,p.revisionId())){s.executeUpdate();}
            for(int i=0;i<p.chunks().size();i++){var x=p.chunks().get(i);try(var s=statement(c,"INSERT INTO knowledge_chunk(tenant_id,document_id,revision_id,chunk_id,ordinal,text_content,start_utf16,end_utf16,start_line,end_line,title_path,model_identity,dimensions,embedding) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?::vector)",tenant,id,p.revisionId(),x.chunkId(),x.ordinal(),x.text(),x.startUtf16(),x.endUtf16(),x.startLine(),x.endLine(),x.titlePath(),embedding.identity(),embedding.dimensions(),vectors.get(i))){s.executeUpdate();}}
            try(var s=statement(c,"UPDATE knowledge_revision SET state=CASE WHEN revision_id=? THEN 'ACTIVE' ELSE 'RETIRED' END WHERE tenant_id=? AND document_id=?",p.revisionId(),tenant,id)){s.executeUpdate();}
            try(var s=statement(c,"UPDATE knowledge_document SET status='ACTIVE',active_revision=?,chunk_count=?,error_code=NULL,updated_at=now() WHERE tenant_id=? AND document_id=? AND version=?",p.revisionId(),p.chunks().size(),tenant,id,version)){if(s.executeUpdate()!=1)throw new Conflict();}
            // Local vectors can be removed in this same transaction. Raw revision snapshots remain for audit.
            try(var s=statement(c,"DELETE FROM knowledge_chunk WHERE tenant_id=? AND document_id=? AND revision_id<>?",tenant,id,p.revisionId())){s.executeUpdate();}
            return new ImportResult("IMPORTED",find(c,id,false));});
        }catch(Conflict e){throw e;}catch(RuntimeException e){recordFailure(id,p.revisionId(),version,"PUBLISH_FAILED");throw e;}
    }
    private void recordFailure(String id,String revision,long version,String code){db.tx(c->{var m=find(c,id,true);if(m.version()==version){try(var s=statement(c,"UPDATE knowledge_document SET error_code=?,status=CASE WHEN active_revision IS NULL THEN 'FAILED' ELSE status END WHERE tenant_id=? AND document_id=?",code,tenant,id)){s.executeUpdate();}try(var s=statement(c,"UPDATE knowledge_revision SET state='FAILED' WHERE tenant_id=? AND document_id=? AND revision_id=?",tenant,id,revision)){s.executeUpdate();}}return null;});}
    public Manifest delete(String id){return db.tx(c->{find(c,id,true);try(var s=statement(c,"UPDATE knowledge_document SET status='DELETED',active_revision=NULL,chunk_count=0,version=version+1,error_code=NULL,updated_at=now() WHERE tenant_id=? AND document_id=?",tenant,id)){s.executeUpdate();}try(var s=statement(c,"UPDATE knowledge_revision SET state='RETIRED' WHERE tenant_id=? AND document_id=?",tenant,id)){s.executeUpdate();}try(var s=statement(c,"DELETE FROM knowledge_chunk WHERE tenant_id=? AND document_id=?",tenant,id)){s.executeUpdate();}return find(c,id,false);});}
    public Search search(String query,int limit){if(query==null||query.isBlank()||query.length()>2000||limit<1||limit>50)throw new IllegalArgumentException("Query required (max 2000 units), limit 1..50");String vector=KnowledgeEmbedding.vectorLiteral(embedding.embed(query),embedding.dimensions());return db.tx(c->{List<Hit> hits=new ArrayList<>();try(var s=statement(c,"SELECT k.*, k.embedding <=> ?::vector AS distance FROM knowledge_chunk k JOIN knowledge_document d ON d.tenant_id=k.tenant_id AND d.document_id=k.document_id AND d.active_revision=k.revision_id WHERE k.tenant_id=? AND k.model_identity=? AND k.dimensions=? AND d.status='ACTIVE' ORDER BY distance,k.chunk_id LIMIT ?",vector,tenant,embedding.identity(),embedding.dimensions(),limit);var r=s.executeQuery()){while(r.next())hits.add(new Hit(r.getString("chunk_id"),r.getString("document_id"),r.getString("revision_id"),r.getString("text_content"),r.getInt("start_utf16"),r.getInt("end_utf16"),r.getInt("start_line"),r.getInt("end_line"),r.getDouble("distance")));}return new Search(query,embedding.identity(),hits);});}
    public Map<String,Object> status(){return db.tx(c->{String pg,vector;try(var s=c.createStatement();var r=s.executeQuery("SELECT version(),(SELECT extversion FROM pg_extension WHERE extname='vector')")){r.next();pg=r.getString(1);vector=r.getString(2);}return Map.of("storage","PostgreSQL + pgvector","embeddingMode",embedding.identity(),"dimensions",embedding.dimensions(),"postgresVersion",pg,"vectorVersion",vector,"tenantId",tenant);});}
}
